add_task(function testMoreThanMaxRecipients() {
  const element = renderMessage([
    recipient("Alice"),
    recipient("Bob"),
    recipient("Carol"),
    recipient("Dave"),
    recipient("Erin"),
  ]);

  Assert.deepEqual(
    getRecipients(element),
    ["Alice", "Bob", "Carol", "2 others"],
    "the recipients should be limited and an 'others' label added"
  );
  element.remove();
});
